INSERT INTO `monalisa_assessments` (`id`, `indikator_id`, `kominfo_created_by`, `kominfo_submitted_by`, `kominfo_updated_by`, `kominfo_scored_by`, `bps_user_id`, `bps_updated_by`, `bps_scored_by`, `kominfo_maturity_level`, `kominfo_justification`, `kominfo_submitted_at`, `kominfo_updated_at`, `bps_maturity_level`, `bps_audit_comment`, `bps_verified_at`, `bps_updated_at`, `status`, `created_at`, `updated_at`) VALUES
('0ac4a61c-40a1-48ed-a315-93e95cbe5b94', 'f8f5df1c-745c-48f6-8330-f5cfb567e8b4', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', '13094c61-3d4a-4b77-bc27-2988f8b0ca6e', '13094c61-3d4a-4b77-bc27-2988f8b0ca6e', '13094c61-3d4a-4b77-bc27-2988f8b0ca6e', '01a68d2e-245d-42cf-ade7-ee13b24e7eb7', '01a68d2e-245d-42cf-ade7-ee13b24e7eb7', '01a68d2e-245d-42cf-ade7-ee13b24e7eb7', 4, 'Penerapan Penerapan Standar Data Statistik telah dilakukan reviu dan evaluasi secara berkala \r\nBukti dukung berisi KAK, JUKNIS, SOP, Dokumen Kebijakan', '2026-04-28 15:28:47', '2026-04-28 15:28:47', NULL, '\"Penggunaan Data Statistik Sektoral yakni Data Jumlah Penduduk Kota Batam dalam Dokumen Rencana Kerja Pemerintah Daerah Tahun 2025\" -> kalau data sektoral itu data dinas selain BPS, jadi mungkin bisa diubah menggunakan data dinas lain, karena kalau data BPS -> indikator 1 -> data dasar. Bukti dukung kalau bisa lebih terupdate, dan berikan contoh yang baru dan relavan dengan indikator', NULL, '2026-05-03 13:40:57', 'rejected', '2026-01-22 15:11:09', '2026-05-03 13:40:57'),
('0b0b6bad-2b06-4792-954d-2b0e43e5c537', 'e197fe9f-12cf-42b4-9892-5586b145c689', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', '529e7cf0-b974-4207-85d1-ab07e1e9c2b1', '529e7cf0-b974-4207-85d1-ab07e1e9c2b1', '529e7cf0-b974-4207-85d1-ab07e1e9c2b1', 4, 'Penerapan Kolaborasi Penyelenggaraan statistik telah dilakukan reviu dan evaluasi secara berkala \r\nBukti dukung berisi KAK, JUKNIS, SOP, Dokumen Kebijakan', '2026-02-03 11:00:01', '2026-02-03 11:00:01', NULL, 'Untuk memperoleh kategori penilaian level 3: Jadi, dokumen yang bernama 30301 Tingkat Kematangan Pengolahan Data - Perikanan.pdf dan 30301 Tingkat Kematangan Pengolahan Data - Disnaker.pdf merupakan ringkasannya. Untuk file-file yang dirangkum dalam dokumen tersebut sebaiknya tetap di upload juga. Harap menambahkan/mengupload dokumen lampiran KAK lengkapnya, Nota Dinas lengkapnya, bukti dukung pengolahan data dari kedua dinas, SK walikota, Peraturan walikota Batam tentang perencanaan tenaga kerja, peraturan walikota tentang SDI, keputusan walikota tentang daftar data pemerintah. Harap memperhatikan tahun pembuatan KAK dan notulennya. \r\nUntuk memperoleh kategori penilaian level 4: Sebaiknya diupload dokumen undangan rapat, daftar hadir, dokumentasi, dan notulen hasil rapat. Selain itu, juga dapat menunjukkan perubahan sebelum dan sesudah adanya revisi/perbaikan, khususnya untuk pengolahan data.', NULL, '2026-05-03 15:46:31', 'rejected', '2026-01-20 09:19:46', '2026-05-03 15:46:31'),
('19fb5ca9-0adc-411f-b495-c5e0b46cdb92', '07c38dab-c0c1-484c-975d-2a2ec68d9160', 'c32a5c11-2eab-4e6d-9ee8-a56e007f0fa9', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', '08e1dc04-1db7-4032-bbc0-65a1e89d9c01', '08e1dc04-1db7-4032-bbc0-65a1e89d9c01', '08e1dc04-1db7-4032-bbc0-65a1e89d9c01', 4, 'Penerapan Kolaborasi Penyelenggaraan statistik telah dilakukan reviu dan evaluasi secara berkala \r\nBukti dukung berisi KAK, JUKNIS, SOP, Dokumen Kebijakan', '2026-02-04 08:28:25', '2026-02-04 08:28:25', NULL, '- Tambahkan bagan formasi ABK tersedia dan terpenuhi\r\n- Untuk masuk ke level 4 tambahkan review smt 1 dan smt 2 misalnya pada smt 1 membahas jumlah ABK tesedia dan berapa yang sudah terisi, untuk smt 2 hasil tindak lanjut', NULL, '2026-04-27 13:50:21', 'rejected', '2026-01-07 13:26:50', '2026-04-27 13:50:21'),
('28e69005-e27e-444f-be80-fe4fe4302b17', '3ea8e622-eabc-4182-9a0b-af55a78b4431', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', 'a453e975-3e18-4ca9-83a2-709ca5bf95de', '529e7cf0-b974-4207-85d1-ab07e1e9c2b1', '529e7cf0-b974-4207-85d1-ab07e1e9c2b1', '529e7cf0-b974-4207-85d1-ab07e1e9c2b1', 4, 'Penerapan Kolaborasi Penyelenggaraan statistik telah dilakukan reviu dan evaluasi secara berkala \r\nBukti dukung berisi KAK, JUKNIS, SOP, Dokumen Kebijakan', '2026-01-20 15:15:41', '2026-01-20 15:15:41', NULL, 'Untuk memperoleh kategori penilaian level 3: Jadi, dokumen yang bernama 30401 Tingkat Kematangan Diseminasi Data - Disnaker.pdf dan 30401 Tingkat Kematangan Diseminasi Data - Perikanan.pdf merupakan ringkasannya. Untuk file-file yang dirangkum dalam dokumen tersebut sebaiknya tetap di upload juga. Harap menambahkan/mengupload dokumen lampiran KAK lengkapnya, Nota Dinas lengkapnya, bukti dukung diseminasi data dari kedua dinas, SK walikota, Peraturan walikota Batam tentang perencanaan tenaga kerja, peraturan walikota tentang SDI, keputusan walikota tentang daftar data pemerintah. Harap memperhatikan tahun pembuatan KAK dan notulennya. \r\n\r\nUntuk memperoleh kategori penilaian level 4: Sebaiknya diupload dokumen undangan rapat, daftar hadir, dokumentasi, dan notulen hasil rapat. Selain itu, juga dapat menunjukkan perubahan sebelum dan sesudah adanya revisi/perbaikan, khususnya untuk diseminasi data.', NULL, '2026-05-03 15:47:57', 'rejected', '2026-01-20 09:22:44', '2026-05-03 15:47:57'),
