INSERT INTO `news` (`id`, `title`, `date`, `category`, `excerpt`, `source_url`, `thumbnail`, `has_video`, `video_url`, `created_at`, `updated_at`) VALUES
('00ebf605-c0f5-465d-8f94-7876789db97d', 'Perkembangan Ekspor Impor Kota Batam, Agustus 2025', '2025-10-02', 'BRS', 'Nilai Ekspor Kota Batam, Agustus 2025, mencapai US$ 1.541,81 juta atau turun 11,58 persen dibandingkan ekspor Juli 2025. Nilai Impor Kota Batam, Agustus 2025, mencapai US$ 1.492,04 juta atau naik sebesar 1,65 persen dibanding impor Juli 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/10/02/718/agustus-2025--ekspor-turun-11-58-persen-dan-impor-naik-1-65-persen.html', NULL, 0, NULL, '2025-10-06 03:07:36', '2025-10-06 03:07:36'),
('0295ab01-c133-4c71-8fed-0194f357408f', 'Perkembangan Pariwisata Kota Batam, Juni 2025', '2025-08-04', 'BRS', 'Pada Juni 2025 jumlah wisman mancanegara ke Kota Batam sebanyak 167.469 kunjungan.  Tingkat Penghunian Kamar Hotel Bintang di Kota Batam sebesar 56,18 persen', 'https://batamkota.bps.go.id/id/pressrelease/2025/08/04/657/jumlah-wisatawan-mancanegara-ke-kota-batam-meningkat-18-91-persen.html', NULL, 1, 'https://www.youtube.com/watch?v=y7Kwrn7j2Xs', '2025-08-05 05:06:24', '2025-08-05 05:07:34'),
('066fb636-5dc6-4b5c-b10d-6e39b975abbb', 'IHK Kota Batam pada November 2025 tercatat 110,41 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,21 persen.', '2025-12-01', 'BRS', 'IHK Kota Batam pada November 2025 tercatat 110,41 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,21 persen.\r\nTingkat inflasi month to month (m-to-m) Kota Batam bulan November 2025 sebesar 0,25  persen, inflasi terjadi karena kenaikan  Indeks Harga Konsumen (IHK) dari 110,14 pada Oktober 2025 menjadi 110,41 pada November 2025.', 'https://batamkota.bps.go.id/id/pressrelease/2025/12/01/702/ihk-kota-batam-pada-november-2025-tercatat-110-41-atau-mengalami-inflasi-year-on-year--y-on-y--sebesar-3-21-persen-.html', NULL, 0, NULL, '2025-12-03 10:42:52', '2025-12-03 10:43:49'),
('0930dc72-07d6-427e-81ea-bd73d92982fa', 'Perkembangan Indeks Harga Konsumen Kota Batam, April 2025', '2025-05-02', 'BRS', 'IHK Kota Batam pada April 2025 tercatat 109,21 atau mengalami inflasi Year on Year (y-o-y) sebesar 2,81 persen ....', 'https://batamkota.bps.go.id/id/pressrelease/2025/05/02/701/pada-april-2025--kota-batam-mengalami-inflasi-year-on-year--y-on-y--sebesar-2-81-persen-dengan-indeks-harga-konsumen--ihk--sebesar-109-21-.html', NULL, 1, 'https://www.youtube.com/watch?v=cTjssxScosc', '2025-05-10 03:00:31', '2025-05-10 03:00:31'),
('0cac141d-b6bc-41cb-911e-0a6416faec07', 'Perkembangan Ekspor Impor Kota Batam, Juni 2025', '2025-08-04', 'BRS', 'Ekspor bulan Juni sebesar US$ 1.553,82 juta atau turun 13,56 persen dibandingkan bulan Mei 2025 dan Impor Juni 2025 sebesar US$ 1.487,61 juta atau turun 15,32 persen dibandingkan impor 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/08/04/716/ekspor-dan-impor-kota-batam-pada-bulan-mei-turun-dari-bulan-sebelumnya.html', NULL, 1, 'https://www.youtube.com/watch?v=y7Kwrn7j2Xs', '2025-08-05 05:05:41', '2025-08-05 05:05:41'),
('0dce4702-cba8-4b25-af43-6ff2ceae5c7d', 'Perkembangan Indeks Harga Konsumen Kota Batam, Juni 2025', '2025-07-01', 'BRS', 'Pada Juni 2025, Kota Batam mengalami inflasi year on year (y-on-y) sebesar 1,68 persen dengan Indeks Harga Konsumen (IHK) sebesar 108,74. Tingkat deflasi month to month (m-to-m) Kota Batam bulan Juni 2025 sebesar 0,06 persen, deflasi terjadi karena penurunan Indeks Harga Konsumen (IHK) dari 108,80 pada Mei 2025 menjadi 108,74 pada Juni 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/07/01/704/ihk-kota-batam-pada-juni-2025-tercatat-108-74-atau-mengalami-inflasi-year-on-year--y-on-y--sebesar-1-68-persen-.html', NULL, 1, 'https://www.youtube.com/embed/SEaqhEYQKgs?si=xTS-AvjbPnGrxQiW', '2025-07-02 00:48:15', '2025-07-02 00:48:15'),
('0e919d25-e966-47e6-90a1-61f77099c2ea', 'Perkembangan Ekspor dan Impor Kota Batam bulan Maret 2026', '2026-05-05', 'BRS', 'Nilai impor Kota Batam Januari-Maret 2026 mencapai US$ 4.523,03 juta atau naik 12,87 persen dibanding periode yang sama tahun 2025.\r\nNilai ekspor Kota Batam Januari-Maret 2026 mencapai US$4.682,73 juta atau turun 0,84 persen dibanding periode yang sama tahun 2025.', 'https://batamkota.bps.go.id/id/pressrelease/2026/05/05/740/perkembangan-ekspor-dan-impor-kota-batam-bulan-maret-2026.html', NULL, 1, 'https://www.youtube.com/embed/h_mEPc-GUow?si=eqjDlE9ZSlNa5JW5', '2026-05-05 13:31:06', '2026-05-05 13:31:06'),
('1611d7bc-beab-4345-b40e-f7571fc66289', 'Perkembangan Transportasi Kota Batam, Maret 2025', '2025-05-05', 'BRS', 'Jumlah Penumpang angkutan udara domestik pada Maret 2025 sebanyak 293.416 orang sedangkan jumlah penumpang angkutan laut domestik pada Maret 2025 sebanyak 342.982 orang ...', 'https://batamkota.bps.go.id/id/pressrelease/2025/05/05/678/maret-2025--jumlah-penumpang-angkutan-udara-domestik-naik-sebesar-6-50-persen-.html', NULL, 0, NULL, '2025-05-10 03:00:31', '2025-05-10 03:00:31'),
('1ead5ccd-1c80-4d62-8b9f-ebc854f718ab', 'Perkembangan Ekspor dan Impor Kota Batam bulan November 2025', '2026-01-05', 'BRS', 'Pada November 2025, nilai Ekspor Kota Batam mencapai US$ 1.630,87 juta atau naik 16,93 persen dibanding ekspor November 2024. Nilai Impor Kota Batam mencapai US$ 1.419,91 juta atau naik 8,51 persen dibanding November 2024.', 'https://batamkota.bps.go.id/id/pressrelease/2026/01/05/723/perkembangan-ekspor-dan-impor-kota-batam-bulan-november-2025.html', NULL, 0, NULL, '2026-01-06 14:32:36', '2026-01-06 14:32:36'),
('21a697e4-72d0-4c49-816f-796000074f18', 'Perkembangan Transportasi Kota Batam, September 2025', '2025-11-04', 'BRS', 'Jumlah penumpang angkutan udara domestik pada September 2025 sebanyak 294.487 orang sedangkan jumlah penumpang angkutan laut domestik pada September 2025 sebanyak 285.050 orang', 'https://batamkota.bps.go.id/id/pressrelease/2025/11/04/684/selisih-penumpang-angkutan-udara-domestik-dan-penumpang-angkutan-laut-domestik-sebesar-9-437-orang.html', NULL, 0, NULL, '2025-11-07 12:04:01', '2025-11-07 12:04:01'),
('2667ec25-720f-4a2a-b3b7-490db3f5175c', 'Perkembangan Indeks Harga Konsumen Kota Batam, Agustus 2025', '2025-09-01', 'BRS', 'Tingkat inflasi (m-to-m) Kota Batam bulan Agustus 2025 sebesar  0,08 persen, terjadi karena kenaikan indeks Harga Konsumen dari 108,90 pada Juli 2025 menjadi 108,99 pada Agustus 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/09/01/706/inflasi--y-o-y--agustus-kota-batam-sebesar-2-37-persen.html', NULL, 1, 'https://batamkota.bps.go.id/id/pressrelease/2025/09/01/706/inflasi--y-o-y--agustus-kota-batam-sebesar-2-37-persen.html', '2025-09-03 05:54:12', '2025-09-04 01:24:10'),
('271ab5bb-8d9d-42f4-8d4c-849af421de4d', 'Perkembangan Pariwisata Kota Batam, Juli 2025', '2025-09-02', 'BRS', 'Jumlah wisatawan mancanegara yang berkunjung ke Kota Batam selama bulan Juli 2025 tercatat sebanyak 123.526 kunjungan. Hal ini mengalami penurunan sebesar 26,24 persen dibanding jumlah wisman bulan sebelumnya.', 'https://batamkota.bps.go.id/id/pressrelease/2025/09/02/658/kunjungan-wisatawan-mancanegara-mencapai-123-526-kunjungan.html', NULL, 1, 'https://batamkota.bps.go.id/id/pressrelease/2025/09/02/658/kunjungan-wisatawan-mancanegara-mencapai-123-526-kunjungan.html', '2025-09-03 05:57:41', '2025-09-04 01:23:09'),
('29878ba3-249e-4108-a1c1-5fb732546287', 'Neraca perdagangan Ekspor Impor kota Batam bulan Oktober sebesar 195,10 juta dolar', '2025-12-02', 'BRS', 'Nilai ekspor kota Batam Oktober 2025 mencapai US$ 1.749,46 juta atau naik sebesar 7,12 persen dibandingkan ekspor September 2025.\r\nNilai impor Kota Batam Oktober 2025 mencapai US$ 1.554,36 juta atau naik sebesar 4,22 persen dibandingkan impor September 2025.', 'https://batamkota.bps.go.id/id/pressrelease/2025/12/02/720/neraca-perdagangan-ekspor-impor-kota-batam-bulan-oktober-sebesar-195-10-juta-dolar.html', NULL, 0, NULL, '2025-12-03 10:44:43', '2025-12-03 10:44:43'),
('2cd3316b-062d-44e6-9cda-c169d805bb0f', 'Perkembangan Indeks Harga Konsumen Kota Batam, Mei 2025', '2025-06-02', 'BRS', 'IHK Kota Batam pada Mei 2025 tercatat 108,80 atau mengalami inflasi Year on Year (y-on-y) sebesar 2,04 persen.Tingkat deflasi m-to-m sebesar 0,38 persen dan tingkat inflasi y-to-d sebesar 1,01 persen.', 'https://batamkota.bps.go.id/id/pressrelease/2025/06/02/703/ihk-kota-batam-pada-mei-2025-tercatat-mengalami-inflasi-year-on-year--y-on-y--sebesar-2-04-persen-.html', NULL, 1, 'https://www.youtube.com/embed/cBw1IE9R5kk?si=d09Args6eW0VXJNQ', '2025-06-02 08:18:29', '2025-06-02 08:18:29'),
('308357f1-c331-46b8-9dc2-3427c3af53f4', 'Pada Oktober 2025 jumlah wisman mancanegara ke Kota Batam sebanyak 139.443 kunjungan', '2025-12-02', 'BRS', 'Jumlah wisatawan mancanegara atau wisman yang berkunjung ke Kota Batam selama bulan Oktober 2025 tercatat sebanyak 139.443 kunjungan. Hal ini mengalami penurunan sebesar 1,77 persen jika dibanding jumlah wisman bulan sebelumnya, dimana jumlah kunjungan wisman pada bulan September 2025 sebanyak 141.958 kunjungan.', 'https://batamkota.bps.go.id/id/pressrelease/2025/12/02/661/pada-oktober-2025-jumlah-wisman-mancanegara-ke-kota-batam-sebanyak-139-443-kunjungan.html', NULL, 0, NULL, '2025-12-03 10:45:17', '2025-12-03 10:45:17'),
('3b2aad86-6f6a-412e-ac17-d435483b474a', 'Perkembangan Indeks Harga Konsumen Kota Batam, Oktober 2025', '2025-11-03', 'BRS', 'IHK Kota batam pada Oktober 2025 tercatat 110,14 atau mengalami inflasi sebesar 3,19 persen dengan nilai Indeks Harga Konsumen (IHK) sebesar 110,14', 'https://batamkota.bps.go.id/id/pressrelease/2025/11/03/708/inflasi-year-on-year--y-on-y--bulan-oktober-2025-sebesar-3-19-persen.html', NULL, 0, NULL, '2025-11-07 12:02:29', '2025-11-07 12:02:29'),
('41cf3e66-e906-45ab-908e-31bcc6f1c765', 'Perkembangan Pariwisata Kota Batam Januari 2026', '2026-03-04', 'BRS', 'Pada Januari 2026 jumlah wisman mancanegara ke Kota Batam sebanyak 126.620 kunjungan. \r\n\r\n TPK hotel bintang di Kota Batam sebesar 53,11 persen.', 'https://batamkota.bps.go.id/id/pressrelease/2026/03/04/732/perkembangan-pariwisata-kota-batam-januari-2026.html', NULL, 1, 'https://youtu.be/3u6nsJJCXpI', '2026-03-06 08:29:08', '2026-03-06 09:07:29'),
('5ee1273c-2a20-4623-8cc9-ae926d5daaf5', 'Penumpang Angkutan Udara dan Laut Kota Batam pada Maret 2026 Mengalami Peningkatan', '2026-05-05', 'BRS', 'Jumlah penumpang angkutan udara dalam negeri (domestik) di Kota Batam pada Maret 2026 tercatat sebanyak 395.868 orang, meningkat sebesar 56,24 persen dibandingkan Februari 2026. Sementara itu, penumpang angkutan udara internasional pada periode yang sama mencapai 15.198 orang atau naik 43,66 persen dibanding bulan sebelumnya.', 'https://batamkota.bps.go.id/id/pressrelease/2026/05/05/739/penumpang-angkutan-udara-dan-laut-kota-batam-pada-maret-2026-mengalami-peningkatan.html', NULL, 1, 'https://www.youtube.com/embed/h_mEPc-GUow?si=eqjDlE9ZSlNa5JW5', '2026-05-05 13:32:52', '2026-05-05 13:32:52'),
('623d9e08-7148-48f1-b613-df7d961d9a47', 'Perkembangan Pariwisata Kota Batam, Agustus 2025', '2025-10-02', 'BRS', 'Jumlah wisatawan mancanegara yang berkunjung ke Kota Batam selama bulan Agustus 2025 tercatat sebanyak 146.897 kunjungan. Hal ini mengalami kenaikan sebesar 18,92 persen jika dibanding jumlah wisatawan bulan sebelumnya.', 'https://batamkota.bps.go.id/id/pressrelease/2025/10/02/659/wisatawan-mancanegara-naik-18-92-persen--dibandingkan-bulan-sebelumnya.html', NULL, 0, NULL, '2025-10-06 03:06:46', '2025-10-06 03:07:04'),
('631cef81-c86f-473a-a26c-cb2b871e12db', 'Perkembangan Pariwisata Kota Batam Maret 2026', '2026-05-05', 'BRS', 'Jumlah wisatawan mancanegara atau wisman yang berkunjung ke Kota Batam selama bulan Maret 2026 tercatat sebanyak 114.837 kunjungan.\r\nWisman yang berkunjung ke Kota Batam pada bulan Maret 2026 didominasi oleh wisman berkebangsaan Singapura mencapai 47,78 persen.', 'https://batamkota.bps.go.id/id/pressrelease/2026/05/05/741/perkembangan-pariwisata-kota-batam-maret-2026.html', NULL, 1, 'https://www.youtube.com/embed/h_mEPc-GUow?si=eqjDlE9ZSlNa5JW5', '2026-05-05 13:32:12', '2026-05-05 13:32:12'),
('68b9a479-841a-4a94-817b-8947c85346f8', 'Pada November 2025 jumlah wisman mancanegara ke Kota Batam sebanyak 127.667 kunjungan. TPK hotel bintang di Kota Batam sebesar 57,36 persen.', '2026-01-05', 'BRS', 'Jumlah wisatawan mancanegara atau wisman yang berkunjung ke Kota Batam selama bulan November 2025 tercatat sebanyak 127.667  kunjungan. Hal ini mengalami  penurunan  sebesar 8,45  persen jika dibanding jumlah wisman bulan sebelumnya, dimana jumlah kunjungan wisman pada bulan Oktober 2025 sebanyak 139.443 kunjungan.', 'https://batamkota.bps.go.id/id/pressrelease/2026/01/05/724/pada-november-2025-jumlah-wisman-mancanegara-ke-kota-batam-sebanyak-127-667-kunjungan---tpk-hotel-bintang-di-kota-batam--sebesar-57-36-persen-.html', NULL, 0, NULL, '2026-01-06 14:33:55', '2026-01-06 14:33:55'),
('690ee430-c360-4796-8fc9-840ee5ec7bbc', 'Angkutan Domestik Menguat, Penumpang Udara Naik 8,77 Persen', '2025-12-02', 'BRS', 'Selama Oktober 2025, arus penumpang transportasi di Kota Batam didominasi oleh peningkatan pada rute domestik. Tercatat jumlah penumpang angkutan udara domestik mencapai 320.312 orang, naik 8,77 persen dibanding September 2025. Tren serupa terjadi pada angkutan laut domestik yang naik 7,37 persen menjadi 306.050 penumpang.', 'https://batamkota.bps.go.id/id/pressrelease/2025/12/02/685/angkutan-domestik-menguat--penumpang-udara-naik-8-77-persen.html', NULL, 0, NULL, '2025-12-03 10:50:11', '2025-12-03 10:50:11'),
('6ca752a9-c050-410e-994b-ff9bf87cd9a2', 'IHK Kota Batam pada Maret 2026 tercatat 112,20 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,13 persen', '2026-04-01', 'BRS', 'IHK Kota Batam pada Maret 2026 tercatat 112,20 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,13 persen.\r\n\r\nMaret 2026 Kota Batam secara month to month (m-to-m) mengalami inflasi  sebesar 0,11  persen, inflasi terjadi karena kenaikan  Indeks Harga Konsumen (IHK) dari 112,08 pada Februari 2026 menjadi 112,20 pada Maret 2026.', 'https://batamkota.bps.go.id/id/pressrelease/2026/04/01/734/ihk-kota-batam-pada-maret-2026-tercatat-112-20-atau-mengalami-inflasi-year-on-year--y-on-y--sebesar-3-13-persen.html', NULL, 1, 'https://www.youtube.com/embed/n0A8gqJyYfA?si=dAcPAW1LdOpn3JpR', '2026-04-05 21:16:07', '2026-04-05 21:16:07'),
('75da0ea1-ad98-45a8-afc3-46fe8e9aa5db', 'Perkembangan Transportasi Kota Batam, April 2025', '2025-06-03', 'BRS', 'Jumlah penumpang angkutan udara domestik pada April 2025 naik sebesar 32,46  persen dan untuk penumpang angkutan laut domestik naik 26,27 persen dibandingkan  Maret 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/06/03/679/penumpang-angkutan-udara-domestik-pada-april-2025-naik-sebesar-32-46--persen-.html', NULL, 1, 'https://www.youtube.com/embed/NLpCMPOp3rE?si=Ph7ga26jpL4gZMUS', '2025-06-04 02:34:50', '2025-06-04 02:38:26'),
('76528faf-7529-4c31-96f4-566f8bcb35f1', 'Perkembangan Pariwisata Kota Batam, September 2025', '2025-11-04', 'BRS', 'Pada September 2025 jumlah wisatawan mancanegara ke Kota Batam sebanyak 141.958 kunjungan dengan tingkat penghunian kamar hotel berbintang mencapai 52,10 persen', 'https://batamkota.bps.go.id/id/pressrelease/2025/11/04/660/wisatawan-mancanegara-yang-berkunjung-ke-batam-sebanyak-141-959-kunjungan.html', NULL, 0, NULL, '2025-11-07 12:03:06', '2025-11-07 12:03:06'),
('7fa8e10e-2581-4249-83bb-402dfe8e931a', 'Perkembangan Transportasi Kota Batam, Juli 2025', '2025-09-02', 'BRS', 'Jumlah penumpang angkutan udara dalam negeri (domestik) pada Juli 2025 sebanyak 337.936 orang atau naik sebesar 4,39 persen dibandingkan Juni 2025. Selain itu penumpang angkutan udara luar negeri atau internasional sebanyak 15.334 orang atau naik 17,34 persen dibandingkan Juni 2025.', 'https://batamkota.bps.go.id/id/pressrelease/2025/09/02/682/penumpang-angkutan-udara-domestik-dan-internasional-naik-pada-juli-2025.html', NULL, 1, 'https://batamkota.bps.go.id/id/pressrelease/2025/09/02/682/penumpang-angkutan-udara-domestik-dan-internasional-naik-pada-juli-2025.html', '2025-09-03 06:39:50', '2025-09-04 01:23:29'),
('7ffad506-8c77-43ee-948d-b14b78f8a992', 'Penumpang Angkutan Laut Internasional pada Desember 2025 Melonjak 43,08 Persen', '2026-02-03', 'BRS', 'Sektor transportasi Kota Batam mencatatkan pertumbuhan positif yang signifikan di seluruh moda transportasi. Kenaikan tertinggi terjadi pada jumlah penumpang angkutan laut internasional yang melonjak sebesar 43,08 persen dibandingkan bulan sebelumnya, dengan total mencapai 603.687 orang. Tren positif juga diikuti oleh angkutan laut domestik yang naik sebesar 24,67 persen menjadi 390.414 orang.', 'https://batamkota.bps.go.id/id/pressrelease/2026/02/03/728/penumpang-angkutan-laut-internasional-pada-desember-2025-melonjak-43-08-persen.html', NULL, 0, NULL, '2026-02-06 14:04:10', '2026-02-06 14:04:10'),
('84f4a369-3567-4fcf-aeac-112d5c938160', 'IHK Kota Batam pada Februari 2026 tercatat 112,08 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,13 persen', '2026-03-02', 'BRS', 'Pada Februari 2026, Kota Batam mengalami inflasi year on year (y-on-y) sebesar 3,13 persen dengan Indeks Harga Konsumen (IHK) sebesar 112,08.\r\n\r\nSecara month to month (m-to-m) mengalami inflasi  sebesar 0,4  persen, inflasi terjadi karena kenaikan  Indeks Harga Konsumen (IHK) dari 111,63 pada Januari 2026 menjadi 112,08 pada Februari 2026.', 'https://batamkota.bps.go.id/id/pressrelease/2026/03/02/730/ihk-kota-batam-pada-februari-2026-tercatat-112-08-atau-mengalami-inflasi-year-on-year--y-on-y--sebesar-3-13-persen.html', NULL, 1, 'https://youtu.be/GyWhex7dGZU', '2026-03-06 08:19:15', '2026-03-06 08:19:15'),
('8f684adb-d2a7-4b86-b2b8-58070b946956', 'Penumpang Angkutan Udara Domestik pada Februari 2026 Turun Sebesar 21,96 Persen', '2026-04-02', 'BRS', 'Perkembangan transportasi di Kota Batam pada Februari 2026 kembali mencatatkan penurunan jumlah penumpang di seluruh moda transportasi dibandingkan bulan sebelumnya (Januari 2026). Jumlah penumpang angkutan udara dalam negeri (domestik) mengalami penurunan tajam sebesar 21,96 persen menjadi 253.375 orang. Penurunan turut terjadi pada penumpang angkutan udara luar negeri (internasional) sebesar 21,33 persen menjadi 10.579 orang.', 'https://batamkota.bps.go.id/id/pressrelease/2026/04/02/737/penumpang-angkutan-udara-domestik-pada-februari-2026-turun-sebesar-21-96-persen.html', NULL, 0, NULL, '2026-04-05 21:18:20', '2026-04-05 21:18:20'),
('8fabda44-4c85-47dd-b86f-9096a03c7d33', 'Perkembangan Pariwisata Kota Batam, April 2025', '2025-06-03', 'BRS', 'Pada April 2025 jumlah wisman ke Kota Batam sebanyak 100.442 kunjungan dengan TPK hotel bintang di Kota Batam sebesar 51,80 persen', 'https://batamkota.bps.go.id/id/pressrelease/2025/06/03/655/pada-april-2025-jumlah-wisman-naik-0-16-persen.html', NULL, 1, 'https://www.youtube.com/embed/NLpCMPOp3rE?si=xUlK5qFD2vkNX9Eb', '2025-06-04 02:27:05', '2025-06-04 02:27:05'),
('9113e402-2b98-4a02-8f04-fa7187a2c30f', 'Perkembangan Ekspor Impor Kota Batam, April 2025', '2025-06-03', 'BRS', 'Ekspor April 2025 sebesar US$ 1.587,89 juta atau naik 6,11 persen dibandingkan ekspor Maret 2025Impor April 2025 sebesar US$ 1.498,31 juta atau naik 13,68 persen dibandingkan impor Maret 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/06/03/714/ekspor-april-2025-sebesar-naik-6-11-persen--dan-impor-april-2025-naik-13-68-persen-dibandingkan-impor-maret-2025.html', NULL, 1, 'https://www.youtube.com/embed/NLpCMPOp3rE?si=Ph7ga26jpL4gZMUS', '2025-06-04 02:33:34', '2025-06-04 02:33:34'),
('9914f752-f64b-424b-9127-ad7973271c7d', 'Penumpang Angkutan Laut Internasional pada Januari 2026 Turun Sebesar 25,12 Persen', '2026-03-04', 'BRS', 'Perkembangan transportasi di Kota Batam pada Januari 2026 secara umum mencatatkan penurunan jumlah penumpang pada seluruh moda transportasi jika dibandingkan dengan bulan sebelumnya (Desember 2025).', 'https://batamkota.bps.go.id/id/pressrelease/2026/03/04/733/penumpang-angkutan-laut-internasional-pada-januari-2026-turun-sebesar-25-12-persen.html', NULL, 1, 'https://youtu.be/3u6nsJJCXpI', '2026-03-06 08:30:10', '2026-03-06 09:07:17'),
('9afd7a11-061f-4169-8cfa-721ba815a369', 'Perkembangan Pariwisata Kota Batam Desember 2025', '2026-02-03', 'BRS', 'Pada Desember 2025 jumlah wisman mancanegara ke Kota Batam sebanyak 195.525 kunjungan.\r\nTPK hotel bintang di Kota Batam  sebesar 63,33 persen.', 'https://batamkota.bps.go.id/id/pressrelease/2026/02/03/729/perkembangan-pariwisata--kota-batam-desember-2025.html', NULL, 0, NULL, '2026-02-06 14:04:34', '2026-02-06 14:04:34'),
('9b2a1729-af51-4c5a-9c14-58ddc115a14e', 'Pada Februari 2026 jumlah wisman mancanegara ke Kota Batam sebanyak 131.308 kunjungan', '2026-04-02', 'BRS', 'Pada Februari 2026, jumlah wisatawan mancanegara (wisman) yang berkunjung ke Kota Batam tercatat sebanyak 131.308 kunjungan, mengalami peningkatan sebesar 3,70 persen dibandingkan Januari 2026 yang mencapai 126.620 kunjungan. Kunjungan wisman pada periode ini didominasi oleh wisatawan berkebangsaan Singapura dengan kontribusi sebesar 43,78 persen dari total kunjungan.', 'https://batamkota.bps.go.id/id/pressrelease/2026/04/02/735/pada-februari-2026-jumlah-wisman-mancanegara-ke-kota-batam-sebanyak-131-308-kunjungan.html', NULL, 0, NULL, '2026-04-05 21:17:16', '2026-04-05 21:17:16'),
('9d143b76-b537-424b-b6c6-fb6208ab9e2f', 'IHK Kota Batam pada April 2026 tercatat 112,77 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,26 persen', '2026-05-04', 'BRS', 'IHK Kota Batam pada April 2026 tercatat 112,77 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,26 persen\r\n\r\nPada April 2026 Kota Batam secara month to month (m-to-m) mengalami inflasi  sebesar 0,51  persen, inflasi terjadi karena kenaikan  Indeks Harga Konsumen (IHK) dari 112,20 pada Maret 2026 menjadi 112,77 pada April 2026.', 'https://batamkota.bps.go.id/id/pressrelease/2026/05/04/738/the-consumer-price-index--cpi--of-batam-municipality-in-april-2026-was-recorded-at-112-77--experiencing-a-year-on-year--y-on-y--inflation-of-3-26-percent.html', NULL, 1, 'https://www.youtube.com/embed/H5B_wjLp7HU?si=3lxFjukL0a8jUIZw', '2026-05-04 15:04:33', '2026-05-04 15:04:33'),
('a4fcebc0-6ea1-4138-9362-eca77a40dd06', 'Perkembangan Indeks Harga Konsumen Kota Batam, September 2025', '2025-10-01', 'BRS', 'Pada September 2025, Kota Batam mengalami inflasi year on year (y-on-y) sebesar 2,82 persen dengan Indeks Harga Konsumen (IHK) sebesar 109,67. Inflasi y-on-y terjadi karena adanya kenaikan harga yang ditunjukkan oleh naiknya sembilan indeks kelompok pengeluaran, yaitu: kelompok makanan, minuman dan tembakau naik sebesar 4,94 persen; kelompok pakaian dan alas kaki naik sebesar 2,71 persen; kelompok perumahan, air, listrik, dan bahan bakar rumah tangga naik sebesar 1,16 persen', 'https://batamkota.bps.go.id/id/pressrelease/2025/10/01/707/inflasi-pada-september-2025--y-on-y---sebesar-2-82-persen.html', NULL, 0, NULL, '2025-10-06 03:09:02', '2025-10-06 03:09:39'),
('b2764ac3-ab01-4d64-9836-aaba2df3ae04', 'IHK Kota Batam pada Desember 2025 tercatat 111,67 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,68 persen.', '2026-01-05', 'BRS', 'IHK Kota Batam pada Desember 2025 tercatat 111,67 atau mengalami inflasi Year on Year (y-on-y) sebesar 3,68 persen.', 'https://batamkota.bps.go.id/id/pressrelease/2026/01/05/725/ihk-kota-batam-pada-desember-2025-tercatat-111-67-atau-mengalami-inflasi-year-on-year--y-on-y--sebesar-3-68-persen-.html', NULL, 1, 'https://www.youtube.com/embed/hzC2IR-fpDA?si=q7v2gyJk6cGBe_-J', '2026-01-06 14:31:35', '2026-01-06 14:31:35'),
('b6759bf2-7c29-4761-9576-606d792672de', 'Perkembangan Ekspor dan Impor Kota Batam bulan Januari 2026', '2026-03-04', 'BRS', 'Ekspor Januari 2026 mencapai US$ 1.592,81 juta\r\nImpor Januari 2026 mencapai US$ 1.579,12 juta', 'https://batamkota.bps.go.id/id/pressrelease/2026/03/04/731/perkembangan-ekspor-dan-impor-kota-batam-bulan-januari-2026.html', NULL, 1, 'https://youtu.be/3u6nsJJCXpI', '2026-03-06 08:28:14', '2026-03-06 09:07:36'),
('c21d57e0-0ae8-4591-b819-9afb9da47121', 'Perkembangan Ekspor Impor Kota Batam, Mei 2025', '2025-07-02', 'BRS', 'Nilai ekspor Kota Batam Mei 2025 mencapai US$ 1.797,48 juta atau naik sebesar 13,20 persen dibandingkan ekspor April 2025. Nilai ekspor nonmigas HS 2 digit terbesar Mei 2025 adalah golongan barang Mesin/Peralatan Listrik (HS 85) sebesar US$ 1.095,39 juta.\r\nNilai impor Kota Batam Mei 2025 mencapai US$ 1.756,77 juta atau naik sebesar 17,25 persen dibandingkan impor April 2025.', 'https://batamkota.bps.go.id/id/pressrelease/2025/07/02/715/ekspor-mei-2025-sebesar-us--1-797-48-juta-atau-naik-13-20-persen-dibandingkan-ekspor-april-2025--impor-mei-2025-sebesar-us--1-756-77-juta-atau-naik-17-25-persen-dibandingkan-impor-april-2025-.html', NULL, 1, 'https://www.youtube.com/embed/4_rMm12ctuk?si=Lvxok6Qf_Wy5qaRv', '2025-07-02 06:42:48', '2025-07-02 06:42:48'),
('c23227bd-09d2-4b4d-929a-aba7b25846e2', 'Perkembangan Transportasi Kota Batam, Juni 2025', '2025-08-04', 'BRS', 'Jumlah penumpang angkutan udara domestik pada Juni 2025 sebanyak 323.711 orang. Jumlah penumpang angkutan laut domestik pada Juni 2025  sebanyak 366.193 orang', 'https://batamkota.bps.go.id/id/pressrelease/2025/08/04/681/penumpang-udara-domestik-naik-16-39-persen.html', NULL, 1, 'https://www.youtube.com/watch?v=y7Kwrn7j2Xs', '2025-08-05 05:07:22', '2025-08-05 05:07:22'),
('d0ef2cb9-ca22-4f25-9c56-4e2774d01935', 'Penumpang Angkutan Laut Domestik pada November 2025 Naik Sebesar 2,32 Persen', '2026-01-05', 'BRS', 'Perkembangan transportasi Kota Batam pada November 2025 mencatat penguatan pada moda angkutan laut domestik. Jumlah penumpang angkutan laut domestik tercatat sebanyak 313.153 orang, atau naik 2,32 persen dibandingkan bulan Oktober 2025. Sebaliknya, penurunan terjadi pada angkutan laut internasional sebesar 2,46 persen menjadi 421.911 orang.', 'https://batamkota.bps.go.id/id/pressrelease/2026/01/05/722/penumpang-angkutan-laut-domestik-pada-november-2025-naik-sebesar-2-32-persen.html', NULL, 0, NULL, '2026-01-06 14:34:29', '2026-01-06 14:34:29'),
('d3754273-939f-4115-b2de-88af824d1fb7', 'Perkembangan Ekspor dan Impor Kota Batam bulan Februari 2026', '2026-04-02', 'BRS', 'Ekspor Februari 2026 mencapai US$ 1.514,65 juta\r\nImpor Februari 2026 mencapai US$ 1.384,67 juta', 'https://batamkota.bps.go.id/id/pressrelease/2026/04/02/736/perkembangan-ekspor-dan-impor-kota-batam-bulan-februari-2026.html', NULL, 0, NULL, '2026-04-05 21:17:46', '2026-04-05 21:17:57'),
('d43d5bf0-e4df-4c0a-8df7-fe6b6e085b8b', 'Perkembangan Ekspor Impor Kota Batam, September 2025', '2025-11-04', 'BRS', 'Ekspor September 2025 sebesar 1,63 milyar dolar atau naik 5,93 persen dibandingkan ekspor Agustus 2025. Sedangkan impor September sebesar 1,49 milyar dolar atau turun 0,04 pesen dibandingkan impor Agustus 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/11/04/719/neraca-perdagangan-ekspor-impor-bulan-september-sebesar-141-77-juta-dolar.html', NULL, 0, NULL, '2025-11-07 12:04:41', '2025-11-07 12:04:41'),
('d45da1d0-66d3-48c3-915b-796a9da1a40c', 'Perkembangan Transportasi Kota Batam, Mei 2025', '2025-07-02', 'BRS', 'Jumlah penumpang angkutan udara dalam negeri (domestik) pada Mei 2025 sebanyak 278.123 orang atau turun sebesar 28,44 persen dibandingkan April 2025. Di sisi lain penumpang angkutan udara luar negeri (internasional) sebanyak 17.376 orang atau naik sebesar 108,45 persen dibandingkan April 2025.', 'https://batamkota.bps.go.id/id/pressrelease/2025/07/02/680/penumpang-udara-domestik-pada-mei-2025-turun-sebesar-28-44-persen--sedangkan-penumpang-udara-internasional-naik-108-45-persen-dibandingkan-bulan-sebelumnya.html', NULL, 1, 'https://www.youtube.com/embed/4_rMm12ctuk?si=Lvxok6Qf_Wy5qaRv', '2025-07-02 06:43:31', '2025-07-02 06:43:31'),
('d49053bb-4e79-4af6-9eae-ea45f4a73dd8', 'Perkembangan Pariwisata Kota Batam, Mei 2025', '2025-07-02', 'BRS', 'Jumlah wisatawan mancanegara atau wisman yang berkunjung ke Kota Batam selama bulan Mei 2025 tercatat sebanyak 140.831 kunjungan. Hal ini mengalami kenaikan sebesar 40,21 persen jika dibanding jumlah wisman bulan sebelumnya, dimana jumlah kunjungan wisman pada bulan April 2025 sebanyak 100.442 kunjungan.\r\nTPK Kota Batam berbintang pada bulan Mei 53,36 persen atau naik 1,56 poin dibandingkan TPK April 2025 yang tercatat 51,80 persen', 'https://batamkota.bps.go.id/id/pressrelease/2025/07/02/656/tpk-hotel-bintang-di-kota-batam-sebesar-53-36-persen-.html', NULL, 1, 'https://www.youtube.com/embed/4_rMm12ctuk?si=Lvxok6Qf_Wy5qaRv', '2025-07-02 06:41:48', '2025-07-02 06:41:48'),
('d95a3d9e-2f16-4e96-86d9-38c0cfaedd02', 'Perkembangan Ekspor Impor Kota Batam, Juli 2025', '2025-09-02', 'BRS', 'Nilai Ekspor Juli 2025 mencapai 1.743,78  juta dollar atau naik 12,23 persen dibandingkan dengan ekspor Juni 2025. Sedangkan Nilai Impor Juli 2025 mencapai 1.467,81  juta dollar atau turun sebesar 1,33 persen dibandingkan impor Juni 2025', 'https://batamkota.bps.go.id/id/pressrelease/2025/09/02/717/ekspor-juli-2025-kota-batam-naik-12-23-persen.html', NULL, 1, 'https://batamkota.bps.go.id/id/pressrelease/2025/09/02/717/ekspor-juli-2025-kota-batam-naik-12-23-persen.html', '2025-09-03 06:39:00', '2025-09-04 01:23:52'),
('dd25d476-4128-458c-9229-dc49d1f6a70c', 'Perkembangan Ekspor dan Impor Kota Batam, Maret 2025', '2025-05-05', 'BRS', 'Ekspor Maret 2025 sebesar US$ 1.496,46 juta atau naik 3,19 persen dibandingkan ekspor Februari 2025. ...', 'https://batamkota.bps.go.id/id/pressrelease/2025/05/05/713/ekspor-maret-2025--naik-3-19-persen-dibandingkan-bulan-lalu-namun-impor-maret-2025--turun-1-09-persen-.html', NULL, 0, NULL, '2025-05-10 03:00:31', '2025-05-10 03:00:31'),
('dead9961-8d3e-4e73-b967-aabb4c492921', 'IHK Kota Batam pada Januari 2026 tercatat 111,63 atau mengalami inflasi Year on Year (y-on-y) sebesar 2,74 persen.', '2026-02-02', 'BRS', 'Pada Januari 2026, Kota Batam mengalami inflasi year on year (y-on-y) sebesar 2,74 persen\r\ndengan Indeks Harga Konsumen (IHK) sebesar 111,63.\r\nSecara month to month (m-to-m) Januari 2025 Kota Batam mengalami deflasi  sebesar\r\n0,04  persen, deflasi terjadi karena penurunan  Indeks Harga Konsumen (IHK) dari 111,67\r\npada Desember 2025 menjadi 111,63 pada Januari 2026.', 'https://batamkota.bps.go.id/id/pressrelease/2026/02/02/726/-ihk-kota-batam-pada-januari-2026-tercatat-111-63-atau-mengalami-inflasi-year-on-year--y-on-y--sebesar-2-74-persen-.html', NULL, 0, NULL, '2026-02-06 14:02:55', '2026-02-06 14:02:55'),
('df97a67e-fe70-4f2d-887a-4a5bf67fe984', 'Perkembangan Ekspor dan Impor Kota Batam bulan Desember 2025', '2026-02-03', 'BRS', 'Pada Desember 2025, nilai Ekspor Kota Batam mencapai US$ 1.651,89 juta atau naik 23,12 persen dibanding ekspor Desember 2024. Nilai Impor Kota Batam mencapai US$ 1.470,58 juta atau naik 15,44 persen dibanding Desember 2024.', 'https://batamkota.bps.go.id/id/pressrelease/2026/02/03/727/perkembangan-ekspor-dan-impor-kota-batam-bulan-desember-2025.html', NULL, 0, NULL, '2026-02-06 14:03:25', '2026-02-06 14:03:25'),
('e76581ca-e165-4ef2-bbc8-ac497c87108a', 'Perkembangan Indeks Harga Konsumen Kota Batam, Juli  2025', '2025-08-01', 'BRS', 'IHK Kota Batam pada Juli 2025 tercatat 108,90 atau mengalami inflasi Year on Year (y-on-y) sebesar 2,30 persen. Tingkat inflasi month to month (m-to-m) Kota Batam bulan Juli 2025 sebesar 0,15  persen, inflasi terjadi karena kenaikan  Indeks Harga Konsumen (IHK) dari 108,74 pada Juni 2025 menjadi 108,90 pada Juli 2025.', 'https://batamkota.bps.go.id/id/pressrelease/2025/08/01/705/pada-juli-2025--kota-batam-mengalami-inflasi-year-on-year--y-on-y--sebesar-2-30-persen-dengan-indeks-harga-konsumen--ihk--sebesar-108-90--inflasi-month-to-month---m-to-m--sebesar-0-15-persen.html', NULL, 1, 'https://www.youtube.com/watch?v=dyRAWNM4psY&t=1s', '2025-08-05 05:04:38', '2025-08-05 05:04:38'),
('ecdce9fd-81a1-46b5-bdd6-c52f4ebf36c6', 'Perkembangan Transportasi Kota Batam, Agustus 2025', '2025-10-02', 'BRS', 'Agustus 2025, jumlah penumpang angkutan udara luar negeri sebanyak 12.440 orang atau turun 18,87 persen dibanding Juli 2025. Dan jumlah penumpang angkutan laut luar negeri, Agustus 2025, sebanyak 443.888 orang atau naik 1,80 persen', 'https://batamkota.bps.go.id/id/pressrelease/2025/10/02/683/penumpang-angkutan-udara-internasional-turun-18-87-persen-sedangkan-penumpang-angkutan-laut-internasional-bauk-1-8-persen.html', NULL, 0, NULL, '2025-10-06 03:05:11', '2025-10-06 03:05:11'),
('ff54f2a2-9fd5-4d1d-af94-25c3eb5b30fe', 'Perkembangan Wisman Mancanegara Kota Batam, Maret 2025', '2025-05-05', 'BRS', 'Pada Maret 2025 jumlah wisman mancanegara ke KotaBatam sebanyak 100.279 kunjungan, dan TPK hotel bintang di Kota Batam sebesar 46,25 persen. ...', 'https://batamkota.bps.go.id/id/pressrelease/2025/05/05/654/pada-maret-2025-jumlah-wisman-mancanegara-ke-kotabatam-sebanyak-100-279-kunjungan--.html', NULL, 0, NULL, '2025-05-10 03:00:31', '2025-05-10 03:00:31');
